import numpy as np

class PhaseModulatedQuadraticSeparable:
    def __init__(self, dim=5):
        self.dim = dim
        # Random phase shifts for each dimension
        self.phases = np.random.uniform(-np.pi, np.pi, size=dim)
        # Random modulation strengths for each dimension
        self.modulations = np.random.uniform(0.5, 1.5, size=dim)

    def f(self, x):
        # Ensure x is within bounds [-5, 5] per dimension
        x = np.clip(x, -5.0, 5.0)
        # Phase-modulated quadratic per dimension
        return np.sum(0.5 * x**2 * (1 + self.modulations * np.sin(x + self.phases)))
